T6.raw_latex:
\begin{thm}
For any binary phylogenetic tree $T$ on a taxon set $X$, the system $Q_T$ of all quartet trees displayed by $T$ contains a meshed system. 
\label{number}
\end{thm}

T7.raw_latex:
\begin{thm}
\label{thm:big}
The  number $k(n)={n \choose 4} - (n-4)$ is the smallest number such that every collection of quartets $\mathcal{S}$ on a taxon set $X=[n]$ such that  $\mathcal{S} \geq k$ is decisive.
\label{minimal}
\end{thm}

T8.raw_latex:
\begin{thm}
The probability $p(X,k)$ that an arbitrary collection of $k$ quartets is decisive has the property 
\[p(X,k) \geq \frac{\sum\limits_{i=1}^{n-3} (-1)^{i+1}{{n-3} \choose i}{{|Q_T|-i(n-3)} \choose {|Q_T|-k}}}{{|Q_T| \choose {k}}}.\]
\end{thm}
